// ─── File: src/main/java/com/bank/diag/ConsumerDiagnosisDemo.java ───
package com.bank.diag;

import java.util.logging.*;

public class ConsumerDiagnosisDemo {
    private static final Logger log = Logger.getLogger(ConsumerDiagnosisDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ConsumerDiagnoser diag = new ConsumerDiagnoser();

        // Cause 1: already committed — current == log-end, zero lag, stable.
        log.info(() -> "Case A → " + diag.diagnose(
            new GroupSnapshot("Stable", 3, 3, 1000, 1000, "earliest", false)));

        // Cause 2: latest on a new group — big lag, current at end, latest policy.
        log.info(() -> "Case B → " + diag.diagnose(
            new GroupSnapshot("Stable", 3, 3, 5000, 0, "latest", true)));

        // Cause 3: more consumers than partitions — some members idle.
        log.info(() -> "Case C → " + diag.diagnose(
            new GroupSnapshot("Stable", 3, 5, 5000, 0, "earliest", false)));

        // Cause 4: stuck rebalancing — group not Stable.
        log.info(() -> "Case D → " + diag.diagnose(
            new GroupSnapshot("PreparingRebalance", 3, 4, 5000, 0, "earliest", false)));
    }
}

