class GroupSnapshot {
    private final String state;           // Stable / PreparingRebalance / CompletingRebalance
    private final int partitions;
    private final int members;
    private final long logEndOffset;      // newest record
    private final long currentOffset;     // committed position
    private final String resetPolicy;     // earliest / latest
    private final boolean brandNewGroup;  // no prior committed offset
    GroupSnapshot(String state, int partitions, int members, long logEndOffset,
                  long currentOffset, String resetPolicy, boolean brandNewGroup) {
            this.state = state;
            this.partitions = partitions
            this.members = members;
            this.logEndOffset = logEndOffset;
            this.currentOffset = currentOffset;
            this.resetPolicy = resetPolicy;
            this.brandNewGroup = brandNewGroup;
    }
    String getState() { return state; }
    int getPartitions() { return partitions; }
    int getMembers() { return members; }
    long getLag() { return logEndOffset - currentOffset; }
    long getLogEndOffset() { return logEndOffset; }
    long getCurrentOffset() { return currentOffset; }
    String getResetPolicy() { return resetPolicy; }
    boolean isBrandNewGroup() { return brandNewGroup; }
}

// ─── Would be in service/ConsumerDiagnoser.java in a real project ───
class ConsumerDiagnoser {
    String diagnose(GroupSnapshot s) {
        // Cause 4 first: an unstable group processes nothing regardless of offsets.
        if (!"Stable".equals(s.getState()))
            return "STUCK REBALANCING (state=" + s.getState()
                 + ") → stabilize membership (fix slow processing / flapping)";
        // Cause 1: everything already consumed.
        if (s.getLag() == 0 && s.getCurrentOffset() >= s.getLogEndOffset())
            return "ALREADY COMMITTED (current==log-end, lag 0) → reset offsets "
                 + "or use a new group.id; Kafka does not redeliver";
        // Cause 2: brand-new group with latest skipped the backlog.
        if (s.isBrandNewGroup() && "latest".equals(s.getResetPolicy()) && s.getLag() > 0)
            return "LATEST SKIPPED BACKLOG → set auto.offset.reset=earliest and "
                 + "reset to earliest to read the " + s.getLag() + " pending records";
        // Cause 3: more consumers than partitions → idle members.
        if (s.getMembers() > s.getPartitions())
            return "MORE CONSUMERS THAN PARTITIONS (" + s.getMembers() + ">" + s.getPartitions()
                 + ") → " + (s.getMembers() - s.getPartitions()) + " idle; add partitions "
                 + "or remove consumers";
        return "Healthy backlog being consumed (lag " + s.getLag() + ")";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
